mapper.insert:
INSERT INTO MSF_SERVICE_ALTER_TRACE (
    NCN
  , CONTRACT_NUM
  , SEQ
  , GLOBAL_NO
  , SUBSCRIBER_NO
  , EVENT_CODE
  , PRCS_MDL_IND
  , TRTM_RSLT_SMST
  , PRCS_SBST
  , RSLT_CD
  , A_SOC_CODE
  , T_SOC_CODE
  , A_SOC_AMNT
  , T_SOC_AMNT
  , PARAMETER
  , ACCESS_IP
  , ACCESS_URL
  , USER_ID
  , SYS_DT
  , SYS_RDATE
) VALUES (
    #{ncn}
  , #{contractNum}
  , (
      SELECT COALESCE(MAX(SEQ), 0) + 1
      FROM MSF_SERVICE_ALTER_TRACE
      WHERE NCN = #{ncn}
        AND SYS_DT = TO_CHAR(NOW(), 'YYYYMMDD')
    )
  , #{globalNo}
  , #{subscriberNo}
  , #{eventCode}
  , #{prcsMdlInd}
  , #{trtmRsltSmst}
  , #{prcsSbst}
  , #{rsltCd}
  , #{aSocCode}
  , #{tSocCode}
  , #{aSocAmnt}
  , #{tSocAmnt}
  , #{parameter}
  , #{accessIp}
  , #{accessUrl}
  , #{userId}
  , TO_CHAR(NOW(), 'YYYYMMDD')
  , NOW()
)
